/// True when now - last > max(3 × period, 1.5 s). Saturating arithmetic.
pub fn is_stale(now_ns: TimeNs, last_ns: TimeNs, period_ns: u64) -> bool;

/// A value with its Validity. Missing data is never zero (ADR-003).
