pub struct Sample { pub t_ns: TimeNs, pub value: f32, pub flags: SampleFlags } // 16 bytes

impl Sample {
    pub const fn valid(t_ns: TimeNs, value: f32) -> Sample;   // flags = VALID
    pub const fn gap(t_ns: TimeNs) -> Sample;                 // value 0.0, flags empty (not VALID)
    pub fn is_valid(&self) -> bool;                           // flags.contains(VALID)
}

/// Engine-owned ring. Not shared with the UI.
pub struct SeriesRing { samples: Box<[Sample]>, next: u32, len: u32, version: u64 }

impl SeriesRing {
    /// Fast-tier capacity for a sampling period: ceil(60 s / period_ns) + 2.
    /// 100 ms gives 602, 1 s gives 62. Panics if period_ns == 0.
    pub const fn fast_capacity(period_ns: u64) -> u32;
    /// Ring with room for `capacity` samples (minimum 2; smaller values are raised to 2).
    pub fn with_capacity(capacity: u32) -> SeriesRing;
    /// Appends, overwriting the oldest sample when full. Increments version by 1.
    pub fn push(&mut self, s: Sample);
    /// Sets GAP_BEFORE on the next pushed sample (used after suspend, rate change, restart).
    pub fn mark_gap(&mut self);
    pub fn len(&self) -> usize;
    pub fn is_empty(&self) -> bool;
    pub fn capacity(&self) -> usize;
    pub fn version(&self) -> u64;
    pub fn last(&self) -> Option<Sample>;
    /// Oldest to newest.
    pub fn iter(&self) -> impl Iterator<Item = Sample> + '_;
    /// Chronological copy for publishing.
    pub fn to_view(&self, id: SeriesId, period_ns: u64) -> SeriesView;
}

/// Published, immutable, chronological copy of a ring.
#[derive(Clone, Debug)]
pub struct SeriesView {
    pub id: SeriesId,
    pub version: u64,       // bumps on every append
    pub period_ns: u64,     // current nominal sampling period
    pub samples: Arc<[Sample]>,
}
```

Rules:
- `mark_gap` stores a pending flag; the next `push` ORs `GAP_BEFORE` into that sample's flags and clears the pending flag. Two `mark_gap` calls before one push set it once.
- `to_view` copies the samples oldest first into one new `Arc<[Sample]>` and copies `version`. Callers reuse the previous `Arc<SeriesView>` when `version` is unchanged (ADR-003: unchanged series reuse their `Arc`); that reuse is the reducer's job (E09).
- Graph ranges are 30 s, 1 min (P1), 5 min and 10 min (P2); the fast tier serves 30 s and 1 min.

