pub enum WaitResult { PsiFired, Timeout, PsiGone }

/// The I/O the loop needs; the real one uses /proc and std::process, tests use a fake.
pub trait WatchIo {
    /// Block until the PSI fd reports POLLPRI, or until `timeout` passes.
    fn wait(&mut self, timeout: std::time::Duration) -> WaitResult;
    fn read_meminfo(&mut self) -> std::io::Result<MemInfo>;
    fn spawn_rescue(&mut self) -> std::io::Result<()>;
    /// true while the last spawned rescue child has not exited (Child::try_wait).
    fn rescue_alive(&mut self) -> bool;
}

/// One loop turn per wait. MemCheck runs when MEMAVAIL_CHECK has passed since the last check.
/// Stops after `max_turns` (None = forever). Returns the number of rescues started.
pub fn run_loop<I: WatchIo>(io: &mut I, max_turns: Option<u64>) -> u64;

/// Entry for `--watch-memory`. Steps:
/// 1. rustix::mm::mlockall(MlockAllFlags::CURRENT | MlockAllFlags::FUTURE); on error log
///    warn!(target: "tasklens::engine", "mlockall failed: {e}") and continue.
/// 2. Open /proc/pressure/memory with O_RDWR | O_NONBLOCK | O_CLOEXEC and write PSI_TRIGGER
///    (including the trailing NUL is not needed). On failure log warn and run with MemAvailable
///    checks only (WaitResult::Timeout every MEMAVAIL_CHECK).
/// 3. PsiGone (POLLERR) reopens the trigger once per MEMAVAIL_CHECK.
/// 4. spawn_rescue runs std::env::current_exe() with the single argument `--low-memory`,
///    stdin, stdout and stderr null, not waited on except through try_wait.
/// 5. Runs until SIGTERM (default action; no handler needed). Returns ExitCode::SUCCESS only if
///    the loop ends.
pub fn run_watch_memory() -> std::process::ExitCode;
